/**
 * soundcn — Free Sound Effects for Modern Web Apps (https://soundcn.xyz/)
 * Curated UI sound effects by kapishdima & Kenney (CC0 / Open Source)
 * 
 * Standalone browser implementation of soundcn Audio Engine using Web Audio API.
 * Embedded with base64 data URIs for zero network latency and offline museum display.
 */

(function(global) {
  'use strict';

  // ============================================================================
  // SOUNDCN REGISTRY & SOUND ASSETS
  // ============================================================================
  const SOUND_REGISTRY = {
  "click-soft": {
    "name": "click-soft",
    "title": "Click Soft",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.007,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 1
  },
  "card-place-1": {
    "name": "card-place-1",
    "title": "Card Place 1",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.689,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 6
  },
  "success-chime": {
    "name": "success-chime",
    "title": "Success Chime",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.49,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 4
  },
  "error-buzz": {
    "name": "error-buzz",
    "title": "Error Buzz",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.104,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 1
  },
  "begin": {
    "name": "begin",
    "title": "Begin",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 1.223,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 10
  },
  "coin-collect": {
    "name": "coin-collect",
    "title": "Coin Collect",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.441,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 4
  },
  "winner": {
    "name": "winner",
    "title": "Winner",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 1.423,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 12
  },
  "toggle-001": {
    "name": "toggle-001",
    "title": "Toggle 001",
    "dataUri": "data:audio/mpeg;base64,",
    "duration": 0.136,
    "license": "CC0",
    "author": "Kenney",
    "sizeKb": 2
  }
};

  // ============================================================================
  // SOUNDCN AUDIO ENGINE (Web Audio API)
  // ============================================================================
  let audioContext = null;
  const bufferCache = new Map();
  let isSoundMuted = false;
  let masterVolume = 0.85;

  function getAudioContext() {
    if (!audioContext) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        audioContext = new AudioCtx();
      }
    }
    if (audioContext && audioContext.state === 'suspended') {
      audioContext.resume().catch(() => {});
    }
    return audioContext;
  }

  async function decodeAudioData(dataUri) {
    if (!dataUri) return null;
    const cached = bufferCache.get(dataUri);
    if (cached) return cached;

    const ctx = getAudioContext();
    if (!ctx) return null;

    try {
      const base64 = dataUri.split(',')[1];
      const binaryString = atob(base64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const audioBuffer = await ctx.decodeAudioData(bytes.buffer.slice(0));
      bufferCache.set(dataUri, audioBuffer);
      return audioBuffer;
    } catch (err) {
      console.warn('[soundcn] Failed to decode audio data URI:', err);
      return null;
    }
  }

  /**
   * Play a sound from the registry or by raw data URI
   * @param {string} soundNameOrKey - Name of registered sound (e.g. 'success-chime') or raw dataUri
   * @param {Object} options - { volume, playbackRate, onEnd, interrupt }
   * @returns {Promise<{ stop: Function } | null>}
   */
  async function playSound(soundNameOrKey, options = {}) {
    if (isSoundMuted) return null;

    const {
      volume = 1,
      playbackRate = 1,
      onEnd = null,
      interrupt = false
    } = options;

    let soundAsset = SOUND_REGISTRY[soundNameOrKey];
    let dataUri = soundAsset ? soundAsset.dataUri : soundNameOrKey;

    if (!dataUri || typeof dataUri !== 'string') {
      console.warn('[soundcn] Unknown sound effect:', soundNameOrKey);
      return null;
    }

    const ctx = getAudioContext();
    if (!ctx) return null;

    if (ctx.state === 'suspended') {
      try {
        await ctx.resume();
      } catch (e) {}
    }

    try {
      const buffer = await decodeAudioData(dataUri);
      if (!buffer) return null;

      const source = ctx.createBufferSource();
      const gain = ctx.createGain();

      source.buffer = buffer;
      source.playbackRate.value = playbackRate;
      
      const effectiveVol = Math.max(0, Math.min(1, volume * masterVolume));
      gain.gain.setValueAtTime(effectiveVol, ctx.currentTime);

      source.connect(gain);
      gain.connect(ctx.destination);

      source.onended = () => {
        if (typeof onEnd === 'function') onEnd();
      };

      source.start(0);

      return {
        stop: () => {
          try {
            source.stop();
          } catch (e) {
            // Already stopped
          }
        }
      };
    } catch (err) {
      console.warn('[soundcn] Error during playback:', err);
      return null;
    }
  }

  // Pre-decode all sounds for ultra-fast instant tactile feedback
  function preloadSounds() {
    const ctx = getAudioContext();
    if (!ctx) return;
    Object.values(SOUND_REGISTRY).forEach(asset => {
      if (asset.dataUri) {
        decodeAudioData(asset.dataUri).catch(() => {});
      }
    });
  }

  // Auto init audio context on first user interaction
  function attachAutoInit() {
    const unlock = () => {
      getAudioContext();
      preloadSounds();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
      window.removeEventListener('touchstart', unlock);
    };
    window.addEventListener('pointerdown', unlock, { once: true, passive: true });
    window.addEventListener('keydown', unlock, { once: true, passive: true });
    window.addEventListener('touchstart', unlock, { once: true, passive: true });
  }

  if (typeof window !== 'undefined') {
    attachAutoInit();
  }

  // Public soundcn API
  const soundcn = {
    // Core methods
    playSound,
    decodeAudioData,
    getAudioContext,
    preloadSounds,
    
    // Convenience triggers
    playClick: (opts) => playSound('click-soft', { volume: 0.7, ...opts }),
    playToggle: (opts) => playSound('toggle-001', { volume: 0.7, ...opts }),
    playCardPlace: (opts) => playSound('card-place-1', { volume: 0.95, ...opts }),
    playCorrect: (opts) => playSound('success-chime', { volume: 0.9, ...opts }),
    playWrong: (opts) => playSound('error-buzz', { volume: 0.75, ...opts }),
    playStart: (opts) => playSound('begin', { volume: 0.85, ...opts }),
    playScore: (opts) => playSound('coin-collect', { volume: 0.85, ...opts }),
    playVictory: (opts) => playSound('winner', { volume: 1.0, ...opts }),

    // Mute / Volume controls
    setMuted: (muted) => {
      isSoundMuted = !!muted;
      return isSoundMuted;
    },
    toggleMute: () => {
      isSoundMuted = !isSoundMuted;
      return isSoundMuted;
    },
    isMuted: () => isSoundMuted,
    setVolume: (vol) => {
      masterVolume = Math.max(0, Math.min(1, vol));
    },
    getVolume: () => masterVolume,

    // Registry inspection
    registry: SOUND_REGISTRY,
    getSoundList: () => Object.keys(SOUND_REGISTRY)
  };

  global.soundcn = soundcn;

})(typeof window !== 'undefined' ? window : this);
